<?php require_once __DIR__.'/../config.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'';if($act==='save'){ $id=(int)($_POST['id']??0);$data=[trim($_POST['name']),trim($_POST['slug']),trim($_POST['description']),trim($_POST['material']),(float)$_POST['price'],(int)$_POST['stock'],(int)$_POST['category_id']];if($id)$pdo->prepare('UPDATE products SET name=?,slug=?,description=?,material=?,price=?,stock=?,category_id=? WHERE id=?')->execute([...$data,$id]);else{$pdo->prepare('INSERT INTO products(name,slug,description,material,price,stock,category_id) VALUES(?,?,?,?,?,?,?)')->execute($data);$id=(int)$pdo->lastInsertId();foreach($pdo->query('SELECT id FROM sizes') as $s)$pdo->prepare('INSERT INTO product_sizes(product_id,size_id,stock) VALUES(?,?,?)')->execute([$id,$s['id'],(int)$_POST['stock']]);}$pdo->prepare('DELETE FROM product_sizes WHERE product_id=?')->execute([$id]);foreach($_POST['sizes']??[] as $sid=>$stock)$pdo->prepare('INSERT INTO product_sizes(product_id,size_id,stock) VALUES(?,?,?)')->execute([$id,(int)$sid,(int)$stock]);$pdo->prepare('DELETE FROM product_size_chart WHERE product_id=?')->execute([$id]);foreach($_POST['chart_label']??[] as $i=>$label)if(trim($label)!=='')$pdo->prepare('INSERT INTO product_size_chart(product_id,label,length_cm,width_cm,notes,sort_order) VALUES(?,?,?,?,?,?)')->execute([$id,trim($label),$_POST['chart_length'][$i]?:null,$_POST['chart_width'][$i]?:null,trim($_POST['chart_notes'][$i]),$i]);flash('success','Produk, ukuran, dan size chart disimpan.');redirect('admin/products.php');}if($act==='delete'){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Produk dihapus.');redirect('admin/products.php');}}$categories=$pdo->query('SELECT * FROM categories')->fetchAll();$allSizes=$pdo->query('SELECT * FROM sizes ORDER BY sort_order')->fetchAll();$edit=null;$selected=[];$chart=[];if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM products WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();$q=$pdo->prepare('SELECT * FROM product_sizes WHERE product_id=?');$q->execute([$edit['id']]);foreach($q as $r)$selected[$r['size_id']]=$r['stock'];$q=$pdo->prepare('SELECT * FROM product_size_chart WHERE product_id=? ORDER BY sort_order');$q->execute([$edit['id']]);$chart=$q->fetchAll();}$products=$pdo->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();$adminTitle='Product management';require __DIR__.'/_header.php';?><div class="grid xl:grid-cols-[1fr_1.4fr] gap-6"><form class="bg-white p-6" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><h2 class="serif text-2xl"><?=$edit?'Edit':'New'?> product</h2><div class="field"><label>Name</label><input required name="name" value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Slug</label><input required name="slug" value="<?=e($edit['slug']??'')?>"></div><div class="field"><label>Category</label><select name="category_id"><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="two-col"><div class="field"><label>Price</label><input type="number" required name="price" value="<?=e((string)($edit['price']??''))?>"></div><div class="field"><label>Total stock</label><input type="number" required name="stock" value="<?=e((string)($edit['stock']??0))?>"></div></div><div class="field"><label>Material</label><input name="material" value="<?=e($edit['material']??'')?>"></div><div class="field"><label>Description</label><textarea name="description"><?=e($edit['description']??'')?></textarea></div><h3 class="font-bold text-sm mt-5">Selectable sizes & stock</h3><p class="text-xs text-slate-500">P · Panjang dan L · Lebar adalah pilihan terpisah dari L.</p><?php foreach($allSizes as $s):?><label class="flex gap-2 items-center text-sm mt-2"><input type="checkbox" name="sizes[<?=$s['id']?>]" value="<?=e((string)($selected[$s['id']]??10))?>" <?=(!$edit||isset($selected[$s['id']]))?'checked':''?> onchange="this.value=this.checked?10:0"> <?=e($s['display_name'])?></label><?php endforeach;?><h3 class="font-bold text-sm mt-5">Size chart (cm)</h3><?php for($i=0;$i<5;$i++):$r=$chart[$i]??[];?><div class="grid grid-cols-4 gap-1 mt-1"><input name="chart_label[]" placeholder="Size" value="<?=e($r['label']??'')?>"><input name="chart_length[]" placeholder="Panjang" value="<?=e((string)($r['length_cm']??''))?>"><input name="chart_width[]" placeholder="Lebar" value="<?=e((string)($r['width_cm']??''))?>"><input name="chart_notes[]" placeholder="Catatan" value="<?=e($r['notes']??'')?>"></div><?php endfor;?><button class="btn gold w-full mt-6">SAVE PRODUCT</button></form><div><table class="data-table"><tr><th>Product</th><th>Category</th><th>Price</th><th></th></tr><?php foreach($products as $p):?><tr><td><b><?=e($p['name'])?></b><br><small><?=e($p['slug'])?></small></td><td><?=e($p['category'])?></td><td><?=money((float)$p['price'])?></td><td><a class="text-link" href="?edit=<?=$p['id']?>">EDIT</a><form method="post" class="inline ml-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="text-red-700 text-xs" onclick="return confirm('Hapus produk?')">DELETE</button></form></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/_footer.php'; ?>
